namespace Erlang.Differential;

public static class FullSweepCaseSources
{
    public const string FullsweepProcessDomain = "-module(fullsweep_process_domain).\n-export([run/0]).\nrun() ->\n    Previous=process_flag(fullsweep_after,17),\n    try\n        17=process_flag(fullsweep_after,65536),\n        {fullsweep_after,0}=process_info(self(),fullsweep_after),\n        0=process_flag(fullsweep_after,65537),\n        {fullsweep_after,1}=process_info(self(),fullsweep_after),\n        lists:foreach(fun(V)->\n            try process_flag(fullsweep_after,V) of _->error(accepted_invalid)\n            catch error:badarg->ok end,\n            {fullsweep_after,1}=process_info(self(),fullsweep_after)\n        end,[-1,1.0,wrong,[],1 bsl 100]), done\n    after process_flag(fullsweep_after,Previous) end.\n";
    public const string FullsweepSpawnForms = "-module(fullsweep_spawn_forms).\n-export([run/0,child/2]).\nrun() ->\n    Parent=self(),Options=[monitor,{fullsweep_after,2},{fullsweep_after,65537}],\n    lists:foreach(fun(Start)->\n        {Pid,Ref}=Start(),\n        receive {Pid,1}->ok after 5000->error(missing_option) end,\n        receive {'DOWN',Ref,process,Pid,normal}->ok after 5000->error(missing_down) end\n    end,[fun()->spawn_opt(fun()->child(Parent,1) end,Options) end,\n         fun()->spawn_opt(node(),fun()->child(Parent,1) end,Options) end,\n         fun()->spawn_opt(fullsweep_spawn_forms,child,[Parent,1],Options) end,\n         fun()->spawn_opt(node(),fullsweep_spawn_forms,child,[Parent,1],Options) end]), done.\nchild(Parent,Expected) ->\n    {fullsweep_after,Expected}=process_info(self(),fullsweep_after),\n    Parent!{self(),process_flag(fullsweep_after,7)},ok.\n";
    public const string FullsweepRequestForms = "-module(fullsweep_request_forms).\n-export([run/0,child/1]).\nrun() ->\n    Parent=self(),Options=[monitor,{fullsweep_after,65538}],\n    lists:foreach(fun(Start)->\n        Ref=Start(),\n        receive {spawn_reply,Ref,ok,Pid}->\n            receive {Pid,2}->ok after 5000->error(missing_option) end,\n            receive {'DOWN',Ref,process,Pid,normal}->ok after 5000->error(missing_down) end\n        after 5000->error(missing_reply) end\n    end,[fun()->spawn_request(fun()->child(Parent) end,Options) end,\n         fun()->spawn_request(node(),fun()->child(Parent) end,Options) end,\n         fun()->spawn_request(fullsweep_request_forms,child,[Parent],Options) end,\n         fun()->spawn_request(node(),fullsweep_request_forms,child,[Parent],Options) end]), done.\nchild(Parent) ->\n    {fullsweep_after,2}=process_info(self(),fullsweep_after),\n    Parent!{self(),process_flag(fullsweep_after,7)},ok.\n";
    public const string FullsweepDefaultSnapshot = "-module(fullsweep_default_snapshot).\n-export([run/0]).\nrun() ->\n    Old=erlang:system_flag(fullsweep_after,3),\n    try\n        {fullsweep_after,3}=erlang:system_info(fullsweep_after),\n        SelfOld=process_flag(fullsweep_after,19),\n        try\n            Parent=self(),\n            {Pid,Ref}=spawn_monitor(fun()->Parent!{self(),process_flag(fullsweep_after,23)} end),\n            receive {Pid,3}->ok after 5000->error(inherited_parent) end,\n            receive {'DOWN',Ref,process,Pid,normal}->ok after 5000->error(missing_down) end,\n            3=erlang:system_flag(fullsweep_after,65536),\n            {fullsweep_after,65535}=erlang:system_info(fullsweep_after),\n            {fullsweep_after,19}=process_info(self(),fullsweep_after), done\n        after process_flag(fullsweep_after,SelfOld) end\n    after erlang:system_flag(fullsweep_after,Old) end.\n";
}
